-- ═══════════════════════════════════════════════════════════════════════
-- Assam Wild Safari — COMPLETE DATABASE SETUP  (one file, always up to date)
--
-- Run in Supabase → SQL Editor. It is SAFE TO RUN AGAIN AND AGAIN:
--   • a new, empty Supabase project  → builds everything and fills the rate cards
--   • your live database             → only adds what is missing; your bookings,
--                                      prices and anything you edited in the admin
--                                      are never changed or deleted
-- Everything runs as one transaction: if a statement fails, nothing changes.
--
-- HOW TO CHANGE THE DATABASE LATER
--   1. New table/column?  Add it in section 1 (table definition) AND, for an
--      existing column list, add a line  "alter table … add column if not exists …"
--      in section 2.  Keep every statement re-runnable (if not exists / on conflict
--      do nothing / where not exists).
--   2. New starting prices or rows?  Add them in section 3 with "on conflict do
--      nothing" so they never overwrite what was changed in the admin.
--   3. Add the new table to the security list in section 4.
--   4. Add one line to the change log at the bottom, then run the whole file.
--
-- Prices are whole rupees.
-- ═══════════════════════════════════════════════════════════════════════

begin;

-- ═════════════════════════ 1. TABLES (final layout) ═════════════════════════

-- One row per person who books. The phone number is the identity
-- (digits only with country code, e.g. 919876543210). "email" is no longer used.
create table if not exists public.customers (
  id          bigint generated by default as identity primary key,
  name        text not null,
  phone       text not null unique,
  email       text,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create table if not exists public.parks (
  id                      text primary key,                 -- 'kaziranga' | 'manas'
  name                    text not null,
  logo_path               text,
  children_need_seat      boolean not null default true,    -- do children count toward the jeep seat limit?
  id_docs_for_all         boolean not null default false,   -- true = every guest uploads an ID
  closed_weekday          smallint check (closed_weekday between 0 and 6),  -- 0 = Sunday … 6 = Saturday
  sort_order              int not null default 0,
  active                  boolean not null default true,
  shared_price_per_person int check (shared_price_per_person >= 0),  -- shared jeep, Indian guests (null = no shared jeep)
  shared_zone_id          text,                              -- the one fixed zone the shared jeep runs in
  shared_price_foreigner  int check (shared_price_foreigner >= 0),   -- shared jeep, foreign guests (includes entry fee)
  camera_still_indian     int check (camera_still_indian >= 0),      -- camera fees per camera (all null = no fee at this park)
  camera_still_foreigner  int check (camera_still_foreigner >= 0),
  camera_video_indian     int check (camera_video_indian >= 0),
  camera_video_foreigner  int check (camera_video_foreigner >= 0)
);

-- Each zone/range is a rate card. Private prices are per jeep.
create table if not exists public.safari_zones (
  id                       text primary key,                -- e.g. 'manas-bansbari'
  park_id                  text not null references public.parks(id),
  name                     text not null,
  price_indian             int  not null check (price_indian >= 0),
  price_foreigner          int  check (price_foreigner >= 0),          -- null = Indian guests only
  shared_price_per_person  int  check (shared_price_per_person >= 0),  -- old per-zone shared price (the park's price is used now)
  max_per_jeep             int  not null default 5 check (max_per_jeep > 0),
  full_day                 boolean not null default false,             -- whole-day zone: no time-slot choice
  note                     text,
  sort_order               int not null default 0,
  active                   boolean not null default true
);

create table if not exists public.safari_slots (
  id          text primary key,                             -- e.g. 'kaz-morning'
  park_id     text not null references public.parks(id),
  name        text not null,                                -- 'Morning'
  time_range  text not null,
  sort_order  int not null default 0,
  active      boolean not null default true,
  for_type    text not null default 'private' check (for_type in ('private', 'shared'))
);

-- Pickup / drop between a city and a park. Prices are one way, per vehicle.
create table if not exists public.transfer_routes (
  id          bigint generated by default as identity primary key,
  park_id     text references public.parks(id),
  city        text not null,                                -- 'Guwahati'
  park_place  text not null,                                -- 'Manas National Park'
  sort_order  int not null default 0,
  active      boolean not null default true
);

create table if not exists public.transfer_rates (
  id            bigint generated by default as identity primary key,
  route_id      bigint not null references public.transfer_routes(id) on delete cascade,
  vehicle_name  text not null,
  seats         int check (seats > 0),
  price         int not null check (price >= 0),
  sort_order    int not null default 0,
  active        boolean not null default true
);

-- Cars for the Car Rental page (itinerary / customised-route requests).
create table if not exists public.vehicles (
  id             uuid primary key default gen_random_uuid(),
  name           text not null,
  capacity       int not null,
  price_per_day  numeric not null default 0,
  description    text,
  active         boolean not null default true,
  created_at     timestamptz default now()
);

create table if not exists public.reviews (
  id          bigint generated by default as identity primary key,
  name        text not null,
  rating      int not null check (rating between 1 and 5),
  message     text not null,
  park        text,
  created_at  timestamptz default now(),
  approved    boolean default false,
  address     text,                           -- optional, private (admin only)
  phone       text,
  email       text
);

-- North East itineraries shown on the website (edited in the admin).
create table if not exists public.itineraries (
  id          bigint generated by default as identity primary key,
  title       text not null unique,
  badge       text,
  route       text,
  num_days    int not null check (num_days >= 1),
  num_nights  int not null check (num_nights >= 0),
  days        jsonb not null default '[]'::jsonb,
  sections    jsonb not null default '[]'::jsonb,
  notes       text,
  sort_order  int not null default 0,
  active      boolean not null default true,
  created_at  timestamptz not null default now()
);

-- Safari booking requests. Flow: requested → (admin sends payment link) awaiting_payment → confirmed.
create table if not exists public.safari_bookings (
  id                       bigint generated by default as identity primary key,
  customer_id              bigint not null references public.customers(id),
  booking_type             text not null check (booking_type in ('private', 'shared')),
  park_id                  text not null references public.parks(id),
  zone_id                  text references public.safari_zones(id),
  zone_name                text not null,     -- copied at booking time so renaming a zone never changes old bookings
  safari_date              date not null,
  slot_label               text not null,
  nationality              text not null default 'indian' check (nationality in ('indian', 'foreigner')),
  num_adults               int  not null check (num_adults >= 1),
  num_children             int  not null default 0 check (num_children >= 0),
  num_jeeps                int  check (num_jeeps >= 1),       -- null for shared seats
  unit_price               int  not null,                     -- per jeep (private) or per person (shared)
  safari_amount            int  not null,
  transfer_amount          int  not null default 0,           -- old: pickup/drop added to a safari (now booked in Car Rental)
  camera_still             int  not null default 0,           -- Manas: number of still cameras
  camera_video             int  not null default 0,           -- Manas: number of video cameras
  camera_amount            int  not null default 0,
  total_amount             int  not null,
  status                   text not null default 'awaiting_payment'
                             check (status in ('requested', 'awaiting_payment', 'pending_review', 'confirmed', 'cancelled')),
  razorpay_order_id        text unique,
  razorpay_payment_link_id text,
  payment_link_url         text,
  payment_link_amount      int,
  payment_requested_at     timestamptz,
  payment_id               text,
  paid_at                  timestamptz,
  vehicle_number           text,
  driver_name              text,
  driver_contact           text,
  admin_notes              text,
  business_name            text,                              -- optional, for business (GST) bookings
  gst_number               text,
  confirmation_emailed_at  timestamptz,                       -- old, unused
  created_at               timestamptz not null default now()
);

create table if not exists public.safari_guests (
  id           bigint generated by default as identity primary key,
  booking_id   bigint not null references public.safari_bookings(id) on delete cascade,
  position     int not null,                 -- 1 = primary guest
  name         text not null,
  age          int not null check (age >= 0),
  is_child     boolean not null default false,
  id_doc_type  text check (id_doc_type in ('aadhaar', 'passport', 'voter_id', 'other')),
  id_doc_path  text,                         -- Netlify Blobs key, viewable from the admin panel
  unique (booking_id, position)
);

-- Car Rental requests. 'transfer' = pickup/drop between a station/airport and a park; 'tour' = car for an itinerary or own route.
create table if not exists public.car_rentals (
  id                       bigint generated by default as identity primary key,
  customer_id              bigint not null references public.customers(id),
  safari_booking_id        bigint references public.safari_bookings(id) on delete set null,  -- old: added during a safari booking
  rental_type              text not null check (rental_type in ('transfer', 'tour')),
  transfer_rate_id         bigint references public.transfer_rates(id) on delete set null,
  route_label              text,
  direction                text check (direction in ('pickup', 'drop', 'both')),
  vehicle_id               uuid references public.vehicles(id) on delete set null,
  itinerary                text,
  itinerary_id             bigint references public.itineraries(id) on delete set null,
  route_description        text,
  num_days                 int check (num_days >= 1),
  vehicle_name             text not null,
  num_vehicles             int not null default 1 check (num_vehicles >= 1),
  num_passengers           int check (num_passengers >= 1),
  start_date               date,
  return_date              date,
  pickup_location          text,
  customer_notes           text,
  amount                   int,                       -- fare / estimate
  status                   text not null default 'requested'
                             check (status in ('awaiting_payment', 'requested', 'confirmed', 'cancelled')),
  razorpay_order_id        text unique,
  payment_id               text,
  paid_at                  timestamptz,
  vehicle_number           text,
  driver_name              text,
  driver_contact           text,
  admin_notes              text,
  business_name            text,
  gst_number               text,
  confirmation_emailed_at  timestamptz,               -- old, unused
  created_at               timestamptz not null default now()
);

-- Itinerary booking requests (a listed itinerary, or the guest's own plan).
create table if not exists public.tour_bookings (
  id                       bigint generated by default as identity primary key,
  customer_id              bigint not null references public.customers(id),
  request_kind             text not null default 'preset' check (request_kind in ('preset', 'custom')),
  itinerary_id             bigint references public.itineraries(id) on delete set null,
  package_key              text,
  package_title            text not null,
  price_per_person         int,
  num_guests               int check (num_guests >= 1),
  start_date               date,
  num_days                 int,
  num_nights               int,
  description              text,
  pickup_drop              text,
  total_amount             int,
  status                   text not null default 'requested' check (status in ('requested', 'confirmed', 'cancelled')),
  customer_notes           text,
  admin_notes              text,
  business_name            text,
  gst_number               text,
  confirmation_emailed_at  timestamptz,               -- old, unused
  created_at               timestamptz not null default now()
);

-- The shared jeep's fixed zone (added after safari_zones exists).
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'parks_shared_zone_id_fkey') then
    alter table public.parks add constraint parks_shared_zone_id_fkey
      foreign key (shared_zone_id) references public.safari_zones(id) on delete set null;
  end if;
end $$;

create index if not exists safari_bookings_date_idx     on public.safari_bookings (safari_date);
create index if not exists safari_bookings_status_idx   on public.safari_bookings (status);
create index if not exists safari_bookings_customer_idx on public.safari_bookings (customer_id);
create index if not exists safari_bookings_link_idx     on public.safari_bookings (razorpay_payment_link_id);
create index if not exists car_rentals_status_idx       on public.car_rentals (status);
create index if not exists car_rentals_safari_idx       on public.car_rentals (safari_booking_id);
create index if not exists car_rentals_date_idx         on public.car_rentals (start_date);
create index if not exists tour_bookings_status_idx     on public.tour_bookings (status);
create index if not exists tour_bookings_date_idx       on public.tour_bookings (start_date);

-- ═══════════ 2. COLUMNS ADDED OVER TIME (for databases built earlier) ═══════════
-- A brand-new database already has all of these from section 1; these lines bring an
-- older live database up to date. Add a line here whenever you add a column.

alter table public.parks
  add column if not exists shared_price_per_person int check (shared_price_per_person >= 0),
  add column if not exists shared_zone_id          text,
  add column if not exists shared_price_foreigner  int check (shared_price_foreigner >= 0),
  add column if not exists camera_still_indian     int check (camera_still_indian >= 0),
  add column if not exists camera_still_foreigner  int check (camera_still_foreigner >= 0),
  add column if not exists camera_video_indian     int check (camera_video_indian >= 0),
  add column if not exists camera_video_foreigner  int check (camera_video_foreigner >= 0);

alter table public.reviews
  add column if not exists address text,
  add column if not exists phone   text,
  add column if not exists email   text;

alter table public.safari_slots
  add column if not exists for_type text not null default 'private';

alter table public.safari_bookings
  add column if not exists razorpay_payment_link_id text,
  add column if not exists payment_link_url         text,
  add column if not exists payment_link_amount      int,
  add column if not exists payment_requested_at     timestamptz,
  add column if not exists camera_still             int not null default 0,
  add column if not exists camera_video             int not null default 0,
  add column if not exists camera_amount            int not null default 0,
  add column if not exists business_name            text,
  add column if not exists gst_number               text;

alter table public.car_rentals
  add column if not exists itinerary_id      bigint references public.itineraries(id) on delete set null,
  add column if not exists route_description text,
  add column if not exists business_name     text,
  add column if not exists gst_number        text;

alter table public.tour_bookings
  add column if not exists request_kind  text not null default 'preset',
  add column if not exists itinerary_id  bigint references public.itineraries(id) on delete set null,
  add column if not exists description   text,
  add column if not exists num_days      int,
  add column if not exists num_nights    int,
  add column if not exists pickup_drop   text,
  add column if not exists business_name text,
  add column if not exists gst_number    text;

-- Requests no longer need every old field (itinerary requests have no guest count / start date / package key).
alter table public.tour_bookings alter column package_key drop not null;
alter table public.tour_bookings alter column num_guests  drop not null;
alter table public.tour_bookings alter column start_date  drop not null;
alter table public.car_rentals   alter column start_date     drop not null;
alter table public.car_rentals   alter column num_passengers drop not null;

-- 'requested' = a new safari request that has no payment link yet.
alter table public.safari_bookings drop constraint if exists safari_bookings_status_check;
alter table public.safari_bookings add constraint safari_bookings_status_check
  check (status in ('requested', 'awaiting_payment', 'pending_review', 'confirmed', 'cancelled'));

-- ═══════════════ 3. STARTING DATA (never overwrites what you edited) ═══════════════

-- Parks. The shared jeep's fixed zone is filled in below once the zones exist (only for parks added by this run).
create temp table _new_parks (id text) on commit drop;
with ins as (
  insert into public.parks (id, name, logo_path, children_need_seat, id_docs_for_all, closed_weekday, sort_order,
                            shared_price_per_person, shared_price_foreigner,
                            camera_still_indian, camera_still_foreigner, camera_video_indian, camera_video_foreigner) values
  ('kaziranga', 'Kaziranga National Park', 'images/kaziranga-logo.png', true, true, null, 1, 1000, 1700, null, null, null, null),
  ('manas', 'Manas National Park', 'images/manas-logo.png', false, false, 2, 2, 1500, 2200, 200, 1000, 10000, 20000)
  on conflict (id) do nothing
  returning id
) insert into _new_parks select id from ins;

-- Safari zones (private jeep price per jeep)
insert into public.safari_zones (id, park_id, name, price_indian, price_foreigner, shared_price_per_person, max_per_jeep, full_day, note, sort_order) values
  ('kaz-central', 'kaziranga', 'Central Range (Kohora)', 3600, 7000, 1000, 5, false, NULL, 1),
  ('kaz-western', 'kaziranga', 'Western Range (Bagori)', 3700, 7100, null, 5, false, NULL, 2),
  ('kaz-eastern', 'kaziranga', 'Eastern Range (Agoratoli)', 3600, 7000, null, 5, false, NULL, 3),
  ('kaz-burapahar', 'kaziranga', 'Burapahar Range', 3600, 7000, null, 5, false, NULL, 4),
  ('manas-bansbari', 'manas', 'Bansbari Zone', 5500, 9000, 1500, 5, false, NULL, 1),
  ('manas-bhuyanpara', 'manas', 'Bhuyan Para Range', 6000, 10000, null, 5, false, NULL, 2),
  ('manas-kahitama', 'manas', 'Kahitama Zone', 6500, 10500, null, 5, false, NULL, 3),
  ('manas-kokilabari', 'manas', 'Kokilabari Zone', 10500, 13000, null, 5, true, 'Whole-day safari', 4),
  ('manas-panbang', 'manas', 'Bansbari to Panbang (Bhutan)', 9200, null, null, 5, true, 'Day trip into Bhutan · Indian guests only', 5)
on conflict (id) do nothing;

update public.parks set shared_zone_id = case id when 'kaziranga' then 'kaz-central' when 'manas' then 'manas-bansbari' end
 where id in (select id from _new_parks) and id in ('kaziranga', 'manas');

