-- Pickup & drop routes (one way, per vehicle)
insert into public.transfer_routes (park_id, city, park_place, sort_order)
select v.park_id, v.city, v.park_place, v.sort_order
from (values
  ('manas', 'Guwahati', 'Manas National Park', 1),
  ('manas', 'Bongaigaon', 'Manas National Park', 2),
  ('manas', 'Barpeta Road', 'Manas National Park', 3),
  ('manas', 'Kaziranga', 'Manas National Park', 4),
  ('kaziranga', 'Kaziranga', 'Guwahati airport / railway station', 5)
) as v(park_id, city, park_place, sort_order)
where not exists (select 1 from public.transfer_routes t where t.city = v.city and t.park_place = v.park_place);

