  ('Bongaigaon', 'Manas National Park', 'Tempo Traveller', 17::int, 5500, 4),
  ('Bongaigaon', 'Manas National Park', 'Winger', 15::int, 6000, 5),
  ('Bongaigaon', 'Manas National Park', 'Tempo Traveller', 26::int, 6500, 6),
  ('Barpeta Road', 'Manas National Park', 'Swift Dzire', null::int, 2000, 1),
  ('Barpeta Road', 'Manas National Park', 'Ertiga', null::int, 2500, 2),
  ('Barpeta Road', 'Manas National Park', 'Innova', null::int, 2800, 3),
