  ('Barpeta Road', 'Manas National Park', 'Tempo Traveller', 17::int, 3500, 5),
  ('Barpeta Road', 'Manas National Park', 'Tempo Traveller', 26::int, 4000, 6),
  ('Kaziranga', 'Manas National Park', 'Swift Dzire', null::int, 9500, 1),
  ('Kaziranga', 'Manas National Park', 'Ertiga (with carrier)', null::int, 12000, 2),
