);

-- North East itineraries (edit them in the admin afterwards)
insert into public.itineraries (title, badge, route, num_days, num_nights, days, sections, notes, sort_order) values
  ('Manas National Park & Panbang (Bhutan)', 'Wildlife + Bhutan', 'Manas National Park → Panbang (Bhutan) → Manas', 4, 3, '[{"text": "Overnight at Manas.", "title": "Receive at Manas National Park"}, {"text": "Morning jeep safari through Manas National Park and Royal Manas up to Panbang, Bhutan. Overnight at Panbang (river side room).", "title": "Jeep safari to Panbang"}, {"text": "Visit the twin waterfalls. After lunch, jungle safari back through the national park. Overnight at Manas.", "title": "Twin waterfalls & jungle safari"}, {"text": "After breakfast, check out.", "title": "Check out"}]'::jsonb, '[{"items": ["Jeep safari 2 nos", "Accommodation", "Breakfast, lunch and dinner", "Bonfire", "Guide", "Bhutan sightseeing vehicle of Bhutan registration"], "heading": "Package includes"}, {"items": ["Rs 13,500 per person for 5 persons"], "heading": "Total package cost"}, {"items": ["Camera charges", "Tea and snacks", "Extra water bottle", "Any other personal expenses"], "heading": "Package excludes"}]'::jsonb, 'Only for Indian tourists. Do not forget to carry your original Voter ID and Aadhaar card for all the members.', 1),
  ('Manas, Raimona National Park & Bhutan', 'Offbeat · Wildlife + Bhutan', 'New Bongaigaon → Raimona → Gelephu → Manas → Panbang → New Bongaigaon', 6, 5, '[{"text": "Arrival at New Bongaigaon railway station and transfer to Raimona National Park (2 hours). After lunch, jeep safari. Halt.", "title": "Arrival at New Bongaigaon → Raimona National Park"}, {"text": "After breakfast, transfer to Gelephu, Bhutan (91 km, 2.5 hours). Halt.", "title": "Transfer to Gelephu, Bhutan"}, {"text": "Gelephu local sightseeing. After lunch, transfer to Manas. Halt.", "title": "Gelephu sightseeing → Manas"}, {"text": "Morning jeep safari to Panbang, Bhutan, inside Manas National Park and Royal Manas, Bhutan. Halt at Bhutan river side accommodation.", "title": "Jeep safari to Panbang, Bhutan"}, {"text": "Morning visit to the twin waterfalls and hanging bridge. After lunch, back to Manas National Park and jeep safari inside the national park. Halt at Manas.", "title": "Twin waterfalls & hanging bridge"}, {"text": "Morning elephant ride (optional). After breakfast, Kakoijana forest (sure sighting of the endangered golden langur). After lunch, drop at New Bongaigaon railway station (15 km) for the Saraighat or Vande Bharat Express. Tour end.", "title": "Elephant ride (optional) & Kakoijana"}]'::jsonb, '[]'::jsonb, 'For Indian tourists only. Do not forget to carry your original Voter ID card and Aadhaar card.', 2),
  ('Guwahati, Shillong, Dawki, Mawlynnong & Cherrapunji', 'Meghalaya Circuit', 'Guwahati → Shillong → Dawki → Mawlynnong → Cherrapunji → Guwahati', 5, 4, '[{"text": "Pickup from Guwahati airport or railway station. Transfer to Shillong. Overnight at Shillong.", "title": "Pickup from Guwahati → Shillong"}, {"text": "Shillong local sightseeing. Stay at Shillong.", "title": "Shillong local sightseeing"}, {"text": "Shillong to Dawki and Mawlynnong village, then transfer to Cherrapunji. Stay at Cherrapunji.", "title": "Shillong → Dawki → Mawlynnong → Cherrapunji"}, {"text": "Cherrapunji local sightseeing. Stay at Cherrapunji.", "title": "Cherrapunji local sightseeing"}, {"text": "Cherrapunji to Guwahati. Evening river cruise. Stay at Guwahati.", "title": "Cherrapunji → Guwahati"}, {"text": "Maa Kamakhya darshan and drop at Guwahati airport or railway station. Tour end.", "title": "Maa Kamakhya darshan & drop"}]'::jsonb, '[]'::jsonb, NULL, 3),
  ('Guwahati, Kaziranga & Tawang (Arunachal Pradesh)', 'Arunachal Circuit', 'Guwahati → Bomdila/Shergaon → Tawang → Dirang → Bhalukpong → Guwahati', 7, 6, '[{"text": "Guwahati to Bomdila or Shergaon via Kalaktang. Stay at Shergaon or Bomdila. 300 km (8 hours).", "title": "Guwahati → Bomdila / Shergaon"}, {"text": "Bomdila to Tawang, 180 km (6 hours), via Sela Pass. Stay at Tawang.", "title": "Bomdila → Tawang via Sela Pass"}, {"text": "Visit Bumla Pass and Sungester Lake. Evening back to Tawang. Stay at Tawang.", "title": "Bumla Pass & Sungester Lake"}, {"text": "Tawang to Dirang (Sangti Valley), 140 km (5 hours). Stay at Dirang.", "title": "Tawang → Dirang (Sangti Valley)"}, {"text": "Dirang to Bhalukpong, 150 km (4 hours). Stay at Bhalukpong.", "title": "Dirang → Bhalukpong"}, {"text": "Bhalukpong to Guwahati, 270 km (5 hours). Stay at Guwahati.", "title": "Bhalukpong → Guwahati"}, {"text": "Morning Maa Kamakhya darshan and drop at Guwahati airport or railway station. Tour end.", "title": "Maa Kamakhya darshan & drop"}]'::jsonb, '[]'::jsonb, NULL, 4),
  ('Guwahati, Shillong, Dawki, Cherrapunji & Kaziranga', 'Meghalaya + Kaziranga', 'Guwahati → Shillong → Dawki → Cherrapunji → Kaziranga → Guwahati', 7, 6, '[{"text": "Pickup from Guwahati airport or railway station. Transfer to Shillong. Overnight at Shillong.", "title": "Pickup from Guwahati → Shillong"}, {"text": "Shillong local sightseeing. Stay at Shillong.", "title": "Shillong local sightseeing"}, {"text": "Shillong to Dawki and Mawlynnong village, then transfer to Cherrapunji. Stay at Cherrapunji.", "title": "Shillong → Dawki → Mawlynnong → Cherrapunji"}, {"text": "Cherrapunji local sightseeing. Stay at Cherrapunji.", "title": "Cherrapunji local sightseeing"}, {"text": "Cherrapunji to Kaziranga. Stay at Kaziranga.", "title": "Cherrapunji → Kaziranga"}, {"text": "Morning 6 AM elephant ride. After breakfast, jeep safari. After lunch, transfer to Guwahati. Stay at Guwahati.", "title": "Elephant ride & jeep safari"}, {"text": "Morning Maa Kamakhya darshan and drop at Guwahati airport or railway station. Tour end.", "title": "Maa Kamakhya darshan & drop"}]'::jsonb, '[]'::jsonb, NULL, 5),
  ('Manas National Park & Arunachal Pradesh (Tawang Sector)', 'Wildlife + Himalayan', 'New Bongaigaon → Manas → Bomdila → Tawang → Dirang → Guwahati', 8, 7, '[{"text": "Pickup from New Bongaigaon station (90 km / 2 hrs). On the way visit Kokoijana forest (sure sighting of the endangered golden langur). Overnight in Manas.", "title": "Arrival at Manas"}, {"text": "Elephant ride (optional) at 6 AM. After lunch: jeep safari. Overnight in Manas.", "title": "Manas safaris"}, {"text": "320 km / 8 hrs. Overnight at Bomdila.", "title": "Manas → Bomdila"}, {"text": "Via Sela Pass (13,700 ft), 180 km / 6 hrs. Overnight at Tawang.", "title": "Bomdila → Tawang via Sela Pass"}, {"text": "Bumla Pass (15,200 ft) and Madhuri Lake. Evening return to Tawang.", "title": "Bumla Pass & Madhuri Lake"}, {"text": "Tawang Monastery, Buddha Statue, Nuranang Falls and Sangti Valley. 140 km / 5 hrs.", "title": "Tawang → Dirang"}, {"text": "Transfer and overnight at Guwahati.", "title": "Dirang → Guwahati"}, {"text": "Kamakhya Temple darshan. Drop at Guwahati airport or railway station. Tour end.", "title": "Kamakhya Temple darshan & drop"}]'::jsonb, '[]'::jsonb, NULL, 6),
  ('Arunachal Anini Tour Package', 'Arunachal Pradesh', 'Dibrugarh Airport → Roing → Anini → Roing → Dibrugarh Airport', 6, 5, '[{"text": "Upon arrival at Dibrugarh Airport, meet our driver and proceed towards Roing, Arunachal Pradesh, via Tinsukia and Dhola–Sadiya Bridge, depending on the selected route and road conditions. Enjoy the scenic journey with suitable breaks for lunch, refreshments and relaxation. On arrival in Roing, check in to the hotel, enjoy dinner and overnight stay. Night stay: Roing. Approximate distance: 150–180 km.", "title": "Dibrugarh Airport pickup → Roing"}, {"text": "After an early breakfast, proceed towards Anini through the beautiful mountain roads of Mayodia Pass and Hunli. Enjoy breathtaking mountain views, lush green forests, misty landscapes and photo stops at safe locations, subject to weather and road conditions. Arrive in Anini, check in to the hotel, enjoy dinner and relax after the long mountain drive. Night stay: Anini. Approximate distance: 200–235 km. Travel note: approximately 7–9 hours or longer, depending on road conditions.", "title": "Roing → Mayodia Pass → Hunli → Anini"}, {"text": "After breakfast, explore Anini town and its surrounding natural beauty: Anini town exploration, scenic mountain viewpoints, beautiful valleys and nature photography, nearby local villages or cultural spots (subject to accessibility and permission) and leisure time to enjoy the peaceful surroundings. Return to the hotel in the afternoon and enjoy a relaxed evening. Night stay: Anini.", "title": "Anini local sightseeing"}, {"text": "After breakfast, enjoy a relaxed day exploring the scenic surroundings of Anini and Dibang Valley: visit accessible valley viewpoints, enjoy panoramic mountain views, explore nearby riverbanks or village areas (subject to road access) and nature photography. Return to the hotel for lunch and relaxation. The sightseeing schedule remains flexible depending on weather, road conditions and local accessibility. Night stay: Anini.", "title": "Anini – Dibang Valley nature excursion"}, {"text": "After breakfast, check out and begin the return journey towards Roing via Hunli and Mayodia Pass. Enjoy the beautiful mountain scenery along the way, with suitable breaks for refreshments and rest. Upon arrival in Roing, check in to the hotel and relax. Dinner and overnight stay. Night stay: Roing. Travel note: allow approximately 7–9 hours or longer, depending on road and weather conditions.", "title": "Anini → Hunli → Mayodia Pass → Roing"}, {"text": "After breakfast, check out and proceed towards Dibrugarh Airport. Enjoy the return drive with suitable refreshment breaks. Arrive at the airport for your onward journey according to your flight schedule. Tour ends with beautiful memories of Arunachal Pradesh.", "title": "Roing → Dibrugarh Airport drop"}]'::jsonb, '[{"items": ["Roing, Mayodia Pass, Hunli, Anini Town, Dibang Valley and scenic mountain landscapes"], "heading": "Tour highlights"}, {"items": ["Duration: 5 Nights / 6 Days", "Pickup point: Dibrugarh Airport", "Drop point: Dibrugarh Airport", "Roing stay: 2 nights", "Anini stay: 3 nights", "Main attractions: Mayodia Pass, Hunli, Anini Town, Dibang Valley and scenic mountain landscapes", "Tour type: Private tour with a comfortable and relaxed travel schedule"], "heading": "Package summary"}, {"items": ["Arunachal Pradesh Inner Line Permit (ILP) must be arranged in advance for Indian tourists.", "Road conditions, weather and local restrictions may affect travel schedules and sightseeing.", "Mayodia Pass and remote sightseeing locations are subject to accessibility and prevailing conditions.", "Guests are advised to carry warm clothing, personal medicines, drinking water and essential travel items.", "Hotel availability and meal arrangements should be confirmed before the tour.", "The itinerary may be adjusted for guest comfort and safety.", "Flight timings should be checked before confirming the pickup and drop schedule."], "heading": "Important notes"}]'::jsonb, 'Recommended travel plan: this itinerary is designed to reduce travel fatigue by keeping two overnight stays in Roing and three nights in Anini, allowing guests to enjoy the mountain journey and local sightseeing at a comfortable pace.', 7)
on conflict (title) do nothing;


-- ═════════════════════════════ 4. SECURITY ═════════════════════════════
-- The website reaches the database only through the Netlify functions (service-role key,
-- which bypasses RLS). The public "anon" key gets no access at all, so nobody can read
-- guest details or ID-document paths straight from Supabase.

do $$
declare t text;
begin
  foreach t in array array[
    'customers', 'parks', 'safari_slots', 'safari_zones', 'transfer_routes', 'transfer_rates',
    'safari_bookings', 'safari_guests', 'car_rentals', 'tour_bookings',
    'itineraries', 'vehicles', 'reviews'
  ] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon, authenticated', t);
  end loop;
end $$;

commit;

